/**
 * GitHub 同步配置上下文（单例）
 *
 * 🔴 根因修复：原来的 useGithubConfig 是普通函数式 hook，每个组件各自 new 一个
 * useState，用户在设置页 saveConfig 后，SyncServiceContext / SyncToGithubButton
 * / 其他消费者读到的仍然是旧 state，导致：
 *   - 右上角一直显示 "GitHub sync not configured"
 *   - 一键同步所有模块直接失败（getGithubApiConfig 始终返回 null）
 *   - 控制台看不到任何 GitHub API 请求（请求根本没发出去）
 *
 * 修复方案：配置提升到 Context 做单例，所有组件共享同一份 config state。
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import { testConnection, type GithubConfig } from '@/lib/github-api';

const CONFIG_KEY = '__app_ledlight_github_config_v1';
const CONFIG_CHANGE_EVENT = 'github-config-change';

export interface GithubConfigData {
  token: string;
  owner: string;
  repo: string;
  branch: string;
  basePath: string;
  enabled: boolean;
  /** Cloudflare Worker 代理地址，配置后走 Worker 代理模式 */
  workerUrl?: string;
}

const DEFAULT_CONFIG: GithubConfigData = {
  token: '',
  owner: '',
  repo: '',
  branch: 'main',
  basePath: '',
  enabled: false,
  workerUrl: '',
};

interface GithubConfigContextValue {
  config: GithubConfigData;
  saveConfig: (newConfig: Partial<GithubConfigData>) => void;
  testing: boolean;
  connectionStatus: 'idle' | 'success' | 'error';
  connectionMessage: string;
  testGithubConnection: (overrideConfig?: Partial<GithubConfigData>) => Promise<boolean>;
  getGithubApiConfig: () => GithubConfig | null;
  /**
   * 获取用于创建询盘 Issue 的配置（宽松模式）
   * 不依赖 enabled 开关，只要有 token + owner + repo 就返回。
   * 询盘邮件通知是独立功能，不应被数据同步开关影响。
   * 强制直连模式（去掉 workerUrl），直接调用 api.github.com。
   */
  getInquiryIssueConfig: () => GithubConfig | null;
  isConfigured: boolean;
}

const GithubConfigContext = createContext<GithubConfigContextValue | null>(null);

/**
 * 规范化 basePath：
 * - 去掉首尾空格
 * - '/' 或空字符串 → 返回 ''（表示仓库根目录，路径前不加前缀）
 * - 否则确保以 / 开头、不以 / 结尾（如 '/docs'）
 */
export function normalizeBasePath(basePath: string): string {
  const trimmed = (basePath ?? '').trim();
  if (!trimmed || trimmed === '/') return '';
  const withLeading = trimmed.startsWith('/') ? trimmed : `/${trimmed}`;
  return withLeading.endsWith('/')
    ? withLeading.slice(0, -1)
    : withLeading;
}

/**
 * 拼接 GitHub 仓库内路径，正确处理 basePath
 * 例如 basePath=''   + path='data/products.json' → 'data/products.json'
 * 例如 basePath='/v2' + path='data/products.json' → 'v2/data/products.json'
 */
export function resolveGithubPath(basePath: string, path: string): string {
  const normalizedBase = normalizeBasePath(basePath);
  // path 本身可能以 / 开头，去掉
  const cleanPath = path.startsWith('/') ? path.slice(1) : path;
  if (!normalizedBase) return cleanPath;
  // normalizedBase 以 / 开头，去掉首位再拼
  return `${normalizedBase.slice(1)}/${cleanPath}`;
}

export function GithubConfigProvider({ children }: { children: ReactNode }) {
  const [config, setConfig] = useState<GithubConfigData>(DEFAULT_CONFIG);
  const [testing, setTesting] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<
    'idle' | 'success' | 'error'
  >('idle');
  const [connectionMessage, setConnectionMessage] = useState('');

  // 加载配置（只在 mount 时执行一次）
  // 优先级：localStorage（裸 key） > 旧 scopedStorage 前缀 key 自动迁移 > window.__GITHUB_CONFIG__（全局注入）> DEFAULT_CONFIG
  useEffect(() => {
    try {
      const saved = localStorage.getItem(CONFIG_KEY);
      if (saved) {
        const parsed = JSON.parse(saved) as Partial<GithubConfigData>;
        const merged = { ...DEFAULT_CONFIG, ...parsed };
        merged.basePath = normalizeBasePath(merged.basePath);
        setConfig(merged);
        logger.info(
          `[GitHub Config] Loaded from localStorage: owner=${merged.owner}, repo=${merged.repo}, branch=${merged.branch}, basePath="${merged.basePath}", enabled=${merged.enabled}, hasToken=${!!merged.token}`
        );
        return;
      }

      // 兼容 V158-V161：之前用 scopedStorage，key 带 __miaoda_<appId>__ 前缀
      // 如果用户升级前已经在后台配过 GitHub，数据存在带前缀的 key 里
      // 这里扫一遍所有 localStorage key，找到包含 CONFIG_KEY 的就迁移到裸 key
      if (typeof window !== 'undefined' && window.localStorage) {
        let found = false;
        try {
          for (let i = 0; i < window.localStorage.length; i++) {
            const k = window.localStorage.key(i);
            if (k && k.includes(CONFIG_KEY) && k !== CONFIG_KEY) {
              const raw = window.localStorage.getItem(k);
              if (raw && raw.startsWith('{')) {
                try {
                  const parsed = JSON.parse(raw) as Partial<GithubConfigData>;
                  if (parsed.owner && parsed.repo) {
                    const merged = { ...DEFAULT_CONFIG, ...parsed };
                    merged.basePath = normalizeBasePath(merged.basePath);
                    try { localStorage.setItem(CONFIG_KEY, JSON.stringify(merged)); } catch (e) { /* ignore */ }
                    setConfig(merged);
                    logger.info(
                      `[GitHub Config] Migrated from legacy key "${k}" to naked localStorage key`
                    );
                    found = true;
                    break;
                  }
                } catch (parseErr) {
                  logger.warn(`[GitHub Config] Failed to parse legacy config at "${k}": ${String(parseErr)}`);
                }
              }
            }
          }
        } catch (fuzzyErr) {
          logger.warn('[GitHub Config] Fuzzy legacy config search failed: ' + String(fuzzyErr));
        }
        if (found) return;
      }

      // localStorage 没有配置，尝试从全局变量读取（静态部署时通过 index.html 注入）
      if (typeof window !== 'undefined') {
        const globalConfig = (window as any).__GITHUB_CONFIG__;
        if (globalConfig && typeof globalConfig === 'object') {
          const merged: GithubConfigData = {
            ...DEFAULT_CONFIG,
            token: String(globalConfig.token || ''),
            owner: String(globalConfig.owner || ''),
            repo: String(globalConfig.repo || ''),
            branch: String(globalConfig.branch || 'main'),
            basePath: normalizeBasePath(String(globalConfig.basePath || '')),
            enabled: Boolean(globalConfig.enabled),
          };
          // 只有配置完整且启用时才使用全局注入
          if (merged.enabled && merged.token && merged.owner && merged.repo) {
            // 写入 localStorage，后续走 localStorage 逻辑
            try {
              localStorage.setItem(CONFIG_KEY, JSON.stringify(merged));
            } catch (e) {
              logger.warn('[GitHub Config] Failed to persist global config to storage: ' + String(e));
            }
            setConfig(merged);
            logger.info(
              `[GitHub Config] Loaded from window.__GITHUB_CONFIG__ (global injection): ` +
              `owner=${merged.owner}, repo=${merged.repo}, enabled=${merged.enabled}, hasToken=${!!merged.token}`
            );
            return;
          }
        }
      }

      logger.info('[GitHub Config] No saved config found in storage or global injection');
    } catch (err) {
      logger.error('[GitHub Config] Failed to load GitHub config:', String(err));
    }
  }, []);

  // 监听跨 tab storage 事件 + 同 tab 自定义事件（Pull Data 后触发刷新）
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key !== CONFIG_KEY || !e.newValue) return;
      try {
        const parsed = JSON.parse(e.newValue) as Partial<GithubConfigData>;
        const merged = { ...DEFAULT_CONFIG, ...parsed };
        merged.basePath = normalizeBasePath(merged.basePath);
        setConfig(merged);
        logger.info(`[GitHub Config] Storage event received, updated config: owner=${merged.owner}, repo=${merged.repo}`);
      } catch (err) {
        logger.warn('[GitHub Config] Failed to parse storage event:', String(err));
      }
    };

    const handleCustomChange = (e: Event) => {
      const detail = (e as CustomEvent<Partial<GithubConfigData>>).detail;
      if (detail && typeof detail === 'object') {
        const merged = { ...DEFAULT_CONFIG, ...detail };
        merged.basePath = normalizeBasePath(merged.basePath || '');
        setConfig(merged);
        logger.info(`[GitHub Config] CustomEvent received, owner=${merged.owner}, repo=${merged.repo}`);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener(CONFIG_CHANGE_EVENT, handleCustomChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener(CONFIG_CHANGE_EVENT, handleCustomChange);
    };
  }, []);

  // 保存配置
  const saveConfig = useCallback((newConfig: Partial<GithubConfigData>) => {
    setConfig((prev) => {
      const next: GithubConfigData = { ...prev, ...newConfig };
      // 规范化 basePath
      if (typeof next.basePath === 'string') {
        next.basePath = normalizeBasePath(next.basePath);
      }
      // 去掉 token/owner/repo 首尾空格（常见 bug 来源）
      if (typeof next.token === 'string') next.token = next.token.trim();
      if (typeof next.owner === 'string') next.owner = next.owner.trim();
      if (typeof next.repo === 'string') next.repo = next.repo.trim();
      if (typeof next.branch === 'string') next.branch = next.branch.trim();

      try {
        localStorage.setItem(CONFIG_KEY, JSON.stringify(next));
        logger.info(
          `[GitHub Config] Saved: owner=${next.owner}, repo=${next.repo}, branch=${next.branch}, basePath="${next.basePath}", enabled=${next.enabled}, hasToken=${!!next.token}`
        );
      } catch (err) {
        logger.error('[GitHub Config] Failed to save GitHub config:', String(err));
        toast.error('Failed to save GitHub configuration');
      }
      return next;
    });
  }, []);

  // 测试连接
  const testGithubConnection = useCallback(async (overrideConfig?: Partial<GithubConfigData>): Promise<boolean> => {
    // 合并配置：优先用 overrideConfig，缺省走当前 config
    const effectiveConfig = { ...config, ...(overrideConfig || {}) };
    const token = (effectiveConfig.token || '').trim();
    const owner = (effectiveConfig.owner || '').trim();
    const repo = (effectiveConfig.repo || '').trim();
    const branch = (effectiveConfig.branch || '').trim();
    const basePath = effectiveConfig.basePath || '';
    const workerUrl = (effectiveConfig.workerUrl || '').trim();
    const useWorker = workerUrl.length > 0;

    // Worker 模式下不需要前端 token（token 在 Worker Secrets 里）
    // 直连模式下必须有 token
    if (!owner || !repo) {
      toast.error('Please fill in Owner and Repository first');
      return false;
    }
    if (!useWorker && !token) {
      toast.error('Please fill in Personal Access Token, or configure a Cloudflare Worker URL.');
      return false;
    }

    setTesting(true);
    setConnectionStatus('idle');
    setConnectionMessage('');

    try {
      logger.info(
        `[GitHub Config] Testing connection: owner=${owner}, repo=${repo}, branch=${branch}`
      );

      const result = await testConnection({
        token,
        owner,
        repo,
        branch,
        basePath,
        workerUrl,
      });

      if (result.success) {
        setConnectionStatus('success');
        setConnectionMessage(result.message);
        toast.success('Connection successful!');
        logger.info('[GitHub Config] Connection test succeeded');
      } else {
        setConnectionStatus('error');
        setConnectionMessage(result.message);
        toast.error(result.message);
        logger.error(`[GitHub Config] Connection test failed: ${result.message}`);
      }
      return result.success;
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Unknown error';
      setConnectionStatus('error');
      setConnectionMessage(msg);
      toast.error('Connection test failed');
      logger.error(`[GitHub Config] Connection test error: ${msg}`);
      return false;
    } finally {
      setTesting(false);
    }
  }, [config]);

  // 获取用于询盘 Issue 创建的配置（宽松模式）
  // 不要求 enabled，只要有 token + owner + repo 就行
  // 强制直连模式，不走 Worker（询盘不依赖 Worker 可用性）
  const getInquiryIssueConfig = useCallback((): GithubConfig | null => {
    const token = (config.token || '').trim();
    const owner = (config.owner || '').trim();
    const repo = (config.repo || '').trim();
    const branch = (config.branch || 'main').trim();
    const basePath = config.basePath || '';

    if (!token || !owner || !repo) {
      logger.warn(
        `[GitHub Config] getInquiryIssueConfig returned null: ` +
        `missing token=${!token}, missing owner=${!owner}, missing repo=${!repo}. ` +
        `Inquiry email notification will NOT work.`
      );
      return null;
    }

    logger.info(
      `[GitHub Config] getInquiryIssueConfig: ok, owner=${owner}, repo=${repo} (direct mode, no worker)`
    );

    // 强制直连模式：workerUrl 设为 undefined
    return {
      token,
      owner,
      repo,
      branch,
      basePath,
      workerUrl: undefined,
    };
  }, [config]);

  // 获取可用的 GitHubConfig（仅当配置完整且启用时）
  // 🔴 强制直连模式：GitHub 数据同步直接调用 api.github.com
  // 用户明确要求 GitHub 同步不走 Worker 代理，Token 存 localStorage
  const getGithubApiConfig = useCallback((): GithubConfig | null => {
    const token = (config.token || '').trim();
    const owner = (config.owner || '').trim();
    const repo = (config.repo || '').trim();
    const branch = (config.branch || 'main').trim();
    const basePath = config.basePath || '';

    const missing = [];
    if (!config.enabled) missing.push('sync not enabled');
    if (!token) missing.push('token missing');
    if (!owner) missing.push('owner missing');
    if (!repo) missing.push('repo missing');
    if (!branch) missing.push('branch missing');

    if (missing.length > 0) {
      logger.warn(
        `[GitHub Config] getGithubApiConfig returned null (${missing.join(', ')}) ` +
        `— GitHub sync will NOT work. ` +
        `Please configure GitHub sync in Admin > GitHub Sync.`
      );
      return null;
    }
    logger.info(
      `[GitHub Config] getGithubApiConfig: ok, owner=${owner}, repo=${repo}, branch=${branch} (direct mode, no worker)`
    );
    // 强制直连模式：workerUrl 设为 undefined，让 ghRequest 走 api.github.com
    return {
      token,
      owner,
      repo,
      branch,
      basePath,
      workerUrl: undefined,
    };
  }, [config]);

  const isConfigured =
    config.enabled &&
    (!!config.token || !!config.workerUrl) &&
    !!config.owner &&
    !!config.repo &&
    !!config.branch;

  const value = useMemo<GithubConfigContextValue>(
    () => ({
      config,
      saveConfig,
      testing,
      connectionStatus,
      connectionMessage,
      testGithubConnection,
      getGithubApiConfig,
      getInquiryIssueConfig,
      isConfigured,
    }),
    [
      config,
      saveConfig,
      testing,
      connectionStatus,
      connectionMessage,
      testGithubConnection,
      getGithubApiConfig,
      getInquiryIssueConfig,
      isConfigured,
    ]
  );

  return (
    <GithubConfigContext.Provider value={value}>
      {children}
    </GithubConfigContext.Provider>
  );
}

export function useGithubConfig(): GithubConfigContextValue {
  const ctx = useContext(GithubConfigContext);
  if (!ctx) {
    throw new Error('useGithubConfig must be used within GithubConfigProvider');
  }
  return ctx;
}
